const payload = await catalogEntityData(server,page.resource,page.id) as EntityPayload | undefined;
if(!payload)throw new Error(`Missing page data: ${server}/${page.resource}/${page.id}`);
if (["jp", "intl", "intl-test"].includes(server) && isCrossCatalogResource(page.resource)) {
  const pin = await staticCatalogRelease(server);
  if (pin.releaseId === payload.releaseId && pin.server === payload.server && pin.sourceId === payload.sourceId) {
    const union = await loadStaticCrossServerEntry(page.resource, server as OfficialCatalogServer, locale, page.id);
    const entry = union.entries.find(entry => entry.perServer[server as OfficialCatalogServer]?.id === page.id);
    const own = entry?.perServer[server as OfficialCatalogServer];
    if (entry && own?.identity.releaseId === pin.releaseId && own.identity.sourceId === pin.sourceId) {
      const detail = await loadCrossServerDetail(entry, server as OfficialCatalogServer, {
        readEntity: (resource, identity, id) => fetchStaticCatalog(`${resource}/${encodeURIComponent(id)}`, identity.server, identity),
      });
      payload.aux = { ...(payload.aux || {}), crossServer: { ...detail, exclusive: entry.exclusive } };
    }
  }
}

if (page.resource === "songs" && ["jp", "intl"].includes(server)) {
  const table = await chartRates(server);
  const musicId = Number((payload.item as Record<string, unknown>).musicId);
  const charts = Object.fromEntries(
    Object.entries(table.charts)
      .filter(([key]) => Number(key.split(":")[0]) === musicId)
      .map(([key, rates]) => [key.split(":")[1], rates]),
  );
  if (Object.keys(charts).length) payload.aux = { ...(payload.aux || {}), chartRates: { greatFactor: table.greatFactor, charts } };
}
